package io.rowweave.expr;

/**
 * Expression engine factory: picks the engine by type, with the compiled engine as default and the interpreter built in as its fallback. Callers take an engine here, so switching does not touch a call site.
 *
 * <p>The default is COMPILED, generating bytecode at run time, controlled by {@code -Drowweave.expr.codegen}: setting it to {@code false} degrades the process to the pure
 * interpreter, which lets an operator switch JIT off without a code change when a JVM misbehaves on generated bytecode. The property is read at
 * call time, so a change takes effect immediately. Both engines draw their semantics from the same {@link ExprRuntime} and produce byte-identical results, so degradation cannot change an answer.
 */
public final class ExprEngineFactory {

    /** Engine kinds. */
    public enum EngineType {
        INTERPRETED,
        COMPILED
    }

    /** System property that degrades at run time. Any value other than "false", including unset, means the compiled engine; "false" means the pure interpreter. */
    public static final String CODEGEN_PROPERTY = "rowweave.expr.codegen";

    private static final ExprEngine INTERPRETED = new InterpretedExprEngine();
    private static final ExprEngine COMPILED = new CompiledExprEngine();

    private ExprEngineFactory() {
    }

    /**
     * Default engine: COMPILED, with the interpreted fallback built in. {@code -Drowweave.expr.codegen=false} degrades to the pure interpreter at run time.
     * Both engines draw semantics from {@link ExprRuntime} and are byte-identical, so degradation cannot change an answer.
     */
    public static ExprEngine getDefault() {
        if ("false".equalsIgnoreCase(System.getProperty(CODEGEN_PROPERTY))) {
            return INTERPRETED;
        }
        return COMPILED;
    }

    /** Creates an engine by type. INTERPRETED returns a singleton; COMPILED returns the JIT engine with its built-in fallback. */
    public static ExprEngine create(EngineType type) {
        switch (type) {
            case INTERPRETED:
                return INTERPRETED;
            case COMPILED:
                return new CompiledExprEngine();
            default:
                throw new IllegalArgumentException("unknown engine type: " + type);
        }
    }
}
